<?php 
    $cats=$db->query('SELECT c.*, (SELECT COUNT(*) FROM articles a WHERE a.category_id=c.id) AS total FROM categories c ORDER BY sort_order,name')->fetchAll(); ?>
    <div class="panel"><h2>Editorias do portal</h2><div class="table-wrap"><table><thead><tr><th>Categoria</th><th>Notícias</th><th></th></tr></thead><tbody><?php foreach($cats as $c): ?><tr><td><strong><?= h($c['name']) ?></strong> <small class="muted">/<?= h($c['slug']) ?></small></td><td><?= (int)$c['total'] ?></td><td><form method="post" action="<?= h(admin_link('delete_category')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="danger-link" data-confirm="Remover a categoria? As notícias serão mantidas sem categoria.">Remover</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><div class="panel" id="new-category"><h2>Nova categoria</h2><form method="post" action="<?= h(admin_link('save_category')) ?>" class="inline-form"><?= csrf_field() ?><input name="name" required maxlength="75" placeholder="Nome da editoria"><button class="btn primary">Adicionar</button></form></div>
